<?php $badge=['draft'=>'secondary','submitted'=>'primary','under_review'=>'warning','approved'=>'success','rejected'=>'danger','withdrawn'=>'dark'];?>
<div class="d-flex flex-wrap justify-content-between gap-3 mb-4"><h1 class="h2">Membership application</h1><div><?php if($application):?><a class="btn btn-outline-primary" href="<?=e(url('/membership/application/documents'))?>">Documents (<?=e(array_sum($documentCounts))?>)</a><?php endif;?> <?php if(!$application||in_array($application['status'],['draft','rejected','withdrawn'],true)):?><a class="btn btn-primary" href="<?=e(url('/membership/application/create'))?>"><?=$application&&$application['status']==='draft'?'Edit draft':($application&&$application['status']==='rejected'?'Correct application':'Start application')?></a><?php endif;?></div></div>
<?php if(!$application):?><div class="card shadow-sm"><div class="card-body p-5 text-center"><h2 class="h4">Not started</h2><p>Complete your profile, then create and review an application.</p><a class="btn btn-primary" href="<?=e(url('/membership/application/create'))?>">Apply</a></div></div><?php else:$applicationStatus=$application['status'];?>
<div class="row g-4"><div class="col-lg-8"><div class="card shadow-sm mb-4"><div class="card-body p-4"><div class="d-flex justify-content-between"><h2 class="h4"><?=e($application['application_number'])?></h2><span class="badge text-bg-<?=e($badge[$applicationStatus]??'secondary')?>"><?=e($statuses->label($applicationStatus))?></span></div><dl class="row"><dt class="col-sm-4">Applicant</dt><dd class="col-sm-8"><?=e($application['name'])?> | <?=e($application['email'])?></dd><dt class="col-sm-4">Contact</dt><dd class="col-sm-8"><?=e($application['telephone']??'Not provided')?> | <?=e($application['province_name']??'Not provided')?></dd><dt class="col-sm-4">Profession</dt><dd class="col-sm-8"><?=e($application['profession_name']??'Not provided')?></dd><dt class="col-sm-4">Organisation / role</dt><dd class="col-sm-8"><?=e(trim(($application['organisation']??'').' | '.($application['job_title']??''),' |')?:'Not provided')?></dd><dt class="col-sm-4">Membership type</dt><dd class="col-sm-8"><?=e($application['membership_type_name'])?></dd><dt class="col-sm-4">Fee</dt><dd class="col-sm-8">Fee to be confirmed.</dd><dt class="col-sm-4">Submitted</dt><dd class="col-sm-8"><?=e($application['submitted_at']?date('j M Y, H:i',strtotime($application['submitted_at'])):'Not submitted')?></dd></dl><a href="<?=e(url('/profile/edit'))?>">Edit profile-controlled details</a><?php if($applicationStatus==='rejected'&&$application['decision_reason']):?><div class="alert alert-danger mt-3"><strong>Decision reason:</strong> <?=e($application['decision_reason'])?></div><?php endif;?></div></div>
<div class="card shadow-sm"><div class="card-body"><h2 class="h4">Timeline</h2><?php if(!$events):?><p>No events yet.</p><?php else:?><ol class="list-group list-group-numbered"><?php foreach($events as $event):?><li class="list-group-item"><strong><?=e($statuses->label($event['new_status']))?></strong> <span class="small text-secondary"><?=e(date('j M Y, H:i',strtotime($event['created_at'])))?></span><?php if($event['note']):?><div><?=e($event['note'])?></div><?php endif;?></li><?php endforeach;?></ol><?php endif;?></div></div></div>
<div class="col-lg-4"><div class="card shadow-sm"><div class="card-body"><h2 class="h5">Next steps</h2><?php if($applicationStatus==='draft'):?><?php if(!$completion['complete']):?><div class="alert alert-warning">Complete <?=e(implode(', ',array_values($completion['missing'])))?>. <a href="<?=e(url('/profile/edit'))?>">Edit profile</a></div><?php endif;?><form method="post" action="<?=e(url('/membership/application/submit'))?>"><?=csrf_field()?><div class="form-check mb-3"><input class="form-check-input" type="checkbox" value="1" name="declaration" id="declaration"><label for="declaration">I declare that this information is accurate.</label></div><button class="btn btn-success w-100">Submit application</button></form><?php elseif(in_array($applicationStatus,['submitted','under_review'],true)):?><p>Awaiting a decision. Documents and payments are deferred.</p><form method="post" action="<?=e(url('/membership/application/withdraw'))?>" onsubmit="return confirm('Withdraw this application? This cannot be undone.')"><?=csrf_field()?><button class="btn btn-outline-danger w-100">Withdraw</button></form><?php elseif($applicationStatus==='approved'):?><p>Application approved. Payment and membership activation have not occurred.</p><?php elseif($applicationStatus==='rejected'):?><p>Correct the application and resubmit.</p><?php else:?><p>This application is withdrawn. You may create a new one.</p><?php endif;?></div></div></div></div><?php endif;?>
